/* Paired North Indian views use the active model; they never change its cusps or planets. */
(()=>{'use strict';const NS='http://www.w3.org/2000/svg',CIRCLE=1296000,norm=n=>((n%CIRCLE)+CIRCLE)%CIRCLE,centres=[[240,60],[120,23],[40,63],[120,125],[40,187],[120,227],[240,187],[360,227],[440,187],[360,125],[440,63],[360,23]],labels=[[240,112],[120,53],[105,67],[225,126],[105,185],[120,201],[240,140],[360,201],[375,185],[255,126],[375,67],[360,53]],polygons=[[[240,0],[360,62.5],[240,125],[120,62.5]],[[0,0],[240,0],[120,62.5]],[[0,0],[120,62.5],[0,125]],[[0,125],[120,62.5],[240,125],[120,187.5]],[[0,125],[120,187.5],[0,250]],[[0,250],[120,187.5],[240,250]],[[240,125],[360,187.5],[240,250],[120,187.5]],[[240,250],[360,187.5],[480,250]],[[360,187.5],[480,125],[480,250]],[[240,125],[360,62.5],[480,125],[360,187.5]],[[480,0],[480,125],[360,62.5]],[[240,0],[480,0],[360,62.5]]];
const $=id=>document.getElementById(id),svg=(tag,attrs={},text)=>{const n=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;};
function houseFor(longitude,cusps){for(let i=0;i<12;i++)if(norm(longitude-cusps[i])<norm(cusps[(i+1)%12]-cusps[i]))return i+1;return null;}
function placement(model,planet,kind){if(kind==='cusp')return Number.isInteger(planet.occ)&&planet.occ>=1&&planet.occ<=12?planet.occ-1:(houseFor(planet.longitude,model.houses.map(c=>c.longitude))||1)-1;return (Math.floor(norm(planet.longitude)/108000)-model.houses[0].signIndex+12)%12;}
function outerPoints(){try{const date=$('dob').value,time=$('birthTime').value,offset=Number($('birth-utc-offset').value),at=new Date(Date.parse(date+'T'+(time.length===5?time+':00':time)+'Z')-offset*3600000),ayan=KPEphemeris.ayanamsha(at);return [['Ur','Uranus'],['Ne','Neptune'],['Pl','Pluto']].map(([id,name])=>{const lon=((Astronomy.Ecliptic(Astronomy.GeoVector(Astronomy.Body[name],at,true)).elon-ayan)%360+360)%360;return {id,name,...KPDisplay.longitudeDetails(lon*3600)};});}catch(_){return [];}}
function planetLabel(point,p){const local=['marathi','hindi','bilingual'].includes(p.language),outer={Ur:['Uranus','युरेनस'],Ne:['Neptune','नेपच्यून'],Pl:['Pluto','प्लुटो']},names={Su:['Sun','रवि'],Mo:['Moon','चंद्र'],Ma:['Mars','मंगळ'],Me:['Mercury','बुध'],Ju:['Jupiter','गुरु'],Ve:['Venus','शुक्र'],Sa:['Saturn','शनि'],Ra:['Rahu','राहू'],Ke:['Ketu','केतू']};if(!local&&p.language!=='english')return window.KPLanguage?.translate((outer[point.id]||names[point.id]||[point.id])[0])||point.id;if(outer[point.id])return p.planetNotation==='short'&&!local?point.id:outer[point.id][local?1:0];return p.planetNotation==='short'?KPPlanetNotation.label(point.id,local?'marathi':'english'):(names[point.id]?.[local?1:0]||point.id);}
function bounds(poly,y){const xs=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length];if(a[1]===b[1]){if(y===a[1])xs.push(a[0],b[0]);}else if(y>=Math.min(a[1],b[1])&&y<=Math.max(a[1],b[1]))xs.push(a[0]+(y-a[1])*(b[0]-a[0])/(b[1]-a[1]));}return [Math.min(...xs)+7,Math.max(...xs)-7];}
function render(target,model,reference=1){reference=Number(reference)||1;if(!target)return;if(!model?.ready){delete target.dataset.pairedNorth;target.replaceChildren(Object.assign(document.createElement('p'),{textContent:'Calculate the active natal or horary chart first.'}));return;}const p=KPPreferences.get(),key=JSON.stringify([reference,model.planets.map(x=>[x.id,x.longitude,x.occ]),model.houses.map(x=>[x.id,x.longitude]),$('dob')?.value,$('birthTime')?.value,$('birth-utc-offset')?.value,p.fontSize,p.planetSize,p.fontBold,p.fontColor,p.language,p.planetNotation,p.themeHeader,p.themeBackground,p.themeStripe,...KPDisplay.ids.map(id=>p['planetColor'+id])]);if(target.dataset.pairedNorth===key)return;target.dataset.pairedNorth=key;const root=document.createElement('div');root.className='kp-paired-north';root.dataset.noLocalize='';root.dataset.houseReference=String(reference);const points=[...model.planets,...outerPoints()],background=p.themeBackground||'#ffffe4',stroke=p.themeHeader||'#6c913b',size=17*(p.fontSize/12)*({small:.85,medium:1,large:1.2}[p.planetSize]||1);
 const zones=[[30,90],[12,43],[36,88],[95,155],[162,214],[207,238],[155,215],[207,238],[162,214],[95,155],[36,88],[12,43]];let uniformSize=size;for(const kind of ['cusp','lagna']){const buckets=Array.from({length:12},()=>[]);for(const point of points)buckets[(placement(model,point,kind)-reference+13)%12].push(point);buckets.forEach((entries,index)=>{const [top,bottom]=zones[index];if(entries.length>1)uniformSize=Math.min(uniformSize,(bottom-top)/(entries.length-1)*.8);entries.forEach((point,row)=>{const y=entries.length===1?centres[index][1]:top+row*(bottom-top)/(entries.length-1),[a,b]=bounds(polygons[index],y),label=planetLabel(point,p);uniformSize=Math.min(uniformSize,(b-a)/(Math.max(1,label.length)*.68));});});}
 for(const [kind,title]of [['cusp','KP Cusp Chart'],['lagna','Lagna Chart']]){const panel=document.createElement('section');panel.className='kp-paired-north-panel';panel.dataset.northBasis=kind;const heading=document.createElement('h4');heading.textContent=title;heading.style.background=p.themeStripe;heading.style.color=p.fontColor;const chart=svg('svg',{viewBox:'0 0 480 250',width:480,height:250,role:'img','aria-label':title+' · active natal or horary chart'});chart.append(svg('title',{},title),svg('rect',{x:1,y:1,width:478,height:248,fill:background,stroke,'stroke-width':1}),svg('path',{d:'M0 0L480 250M480 0L0 250M240 0L480 125L240 250L0 125Z',stroke,'stroke-width':.7,fill:'none'}));const sectors=Array.from({length:12},()=>[]);for(const point of points)sectors[(placement(model,point,kind)-reference+13)%12].push(point);
 sectors.forEach((entries,index)=>{const sign=kind==='cusp'?model.houses[(index+reference-1)%12].signIndex+1:(model.houses[0].signIndex+index+reference-1)%12+1,g=svg('g',{'data-house':index+1,'data-sign':sign}),[lx,ly]=labels[index];g.append(svg('text',{x:lx,y:ly,'text-anchor':'middle','font-size':11,fill:stroke},sign));const [top,bottom]=zones[index];entries.forEach((point,row)=>{const y=entries.length===1?centres[index][1]:top+row*(bottom-top)/(entries.length-1),[a,b]=bounds(polygons[index],y),label=planetLabel(point,p),colour=p['planetColor'+point.id]||p.fontColor||'#111111',n=svg('text',{x:(a+b)/2,y,'text-anchor':'middle','dominant-baseline':'middle','font-size':uniformSize,'font-weight':600,fill:colour,'data-planet':point.id,'data-chart-longitude':point.longitude},label);for(const [property,value]of Object.entries({'fill':colour,'stroke':'none','font-size':uniformSize+'px','font-family':"Arial, 'Nirmala UI', sans-serif",'font-weight':'600'}))n.style.setProperty(property,value,'important');n.append(svg('title',{},planetLabel(point,p)+' · '+(kind==='cusp'?'KP house ':'Lagna house ')+(index+1)));g.append(n);});chart.append(g);});panel.append(heading,chart);root.append(panel);}target.replaceChildren(root);}
function refresh(){window.KPChartStyle?.refresh();window.dispatchEvent(new CustomEvent('kundali-style-changed',{detail:{style:window.KPChartStyle?.getStyle(),source:'paired-north'}}));}window.KPPairedNorth=Object.freeze({render,placement,houseFor});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(refresh,350));else setTimeout(refresh,350);window.addEventListener('kp-preferences-changed',refresh);window.addEventListener('chart-saved',refresh);})();
